parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "full_name": {
      "type": "string",
      "description": "Applicant's full name"
    },
    "email": {
      "type": "string",
      "description": "Email address written in the CV"
    },
    "phone": {
      "type": "string",
      "description": "Mobile/phone number exactly as written, including country code if present"
    },
    "location": {
      "type": "string",
      "description": "City / country of residence"
    },
    "linkedin": {
      "type": "string",
      "description": "LinkedIn profile URL"
    },
    "education": {
      "type": "string",
      "description": "Highest or current qualification, institution and year, as one short line"
    },
    "skills": {
      "type": "string",
      "description": "Key technical skills, comma-separated"
    },
    "total_experience_years": {
      "type": "number",
      "description": "Total years of paid work experience of any kind (0 if none, decimals allowed)"
    },
    "has_relevant_experience": {
      "type": "boolean",
      "description": "true only if the applicant has held at least one job, internship, part-time or freelance role related to the position applied for"
    },
    "relevant_experience_details": {
      "type": "string",
      "description": "The relevant roles as 'Title @ Company (duration)', separated by '; '. Empty string if none."
    },
    "summary": {
      "type": "string",
      "description": "Two-sentence summary of the candidate for a recruiter"
    }
  },
  "required": [
    "full_name",
    "email",
    "phone",
    "has_relevant_experience",
    "total_experience_years",
    "summary"
  ]
}

